// Build-time only: node deploy/build-images.mjs /absolute/path/to/sharp/lib/index.js
// Keep the original artwork; generated filenames are immutable content hashes.
import {createRequire} from 'node:module';
import {readFile,writeFile,mkdir,readdir} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {fileURLToPath} from 'node:url';
import path from 'node:path';
const require=createRequire(import.meta.url),sharp=require(process.argv[2]||'sharp');
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../public');
await mkdir(path.join(root,'media'),{recursive:true});
const images={backgrounds:{},ranks:{},maps:{}};
async function convert(source,stem,width,quality){
 const input=await readFile(path.join(root,source));
 const output=await sharp(input).resize({width,withoutEnlargement:true}).webp({quality,effort:6}).toBuffer();
 const hash=createHash('sha256').update(output).digest('hex').slice(0,16);
 const url=`/media/${stem}.${hash}.webp`;
 await writeFile(path.join(root,url.slice(1)),output);
 console.log(`${stem}: ${input.length} -> ${output.length} bytes`);
 return url;
}
for(const stem of ['castle-dawn','castle-stone','campaign-map','calradia-banner'])images.backgrounds[stem]=await convert(stem+'.png',stem,1920,82);
for(const name of ['Joker','Peasant','Guard','Knight','MasterKnight','Lord','Duke','Prince','King','Emperor']){
 images.ranks[name]={thumb:await convert(`ranks/tarot/${name}.png`,name+'-320',320,82),card:await convert(`ranks/tarot/${name}.png`,name+'-640',640,85)};
}
for(const file of (await readdir(path.join(root,'maps'))).filter(f=>f.endsWith('.jpg'))){const stem=file.slice(0,-4);images.maps[stem]=await convert('maps/'+file,stem,960,82);}
await writeFile(path.join(root,'image-assets.js'),'// Generated by deploy/build-images.mjs; do not hand-edit URLs.\nexport const imageAssets='+JSON.stringify(images,null,2)+';\n');
// Update both original URLs and previous generated versions on subsequent builds.
for(const file of (await readdir(root)).filter(f=>f.endsWith('.css'))){
 const previous=await readFile(path.join(root,file),'utf8');let next=previous;
 for(const [stem,url] of Object.entries(images.backgrounds))next=next.replaceAll('/'+stem+'.png',url).replace(new RegExp('/media/'+stem+'\\.[a-f0-9]{16}\\.webp','g'),()=>url);
 if(next!==previous)await writeFile(path.join(root,file),next);
}
